package com.ianblk.zianmobs.client;
import com.google.gson.*;
import com.ianblk.zianmobs.MobsNetwork;
import com.ianblk.zianmobs.core.AdminSections;
import com.ianblk.zianmobs.core.QuickEncounter;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.*;
import net.minecraft.network.chat.Component;
import net.neoforged.neoforge.network.PacketDistributor;
import java.util.*;

/** Guided dashboard and grouped forms. Hidden tabs retain their values until the server saves. */
public final class MobsScreen extends ManagerThemedScreen {
 private final JsonObject data;private final Map<String,String> values=new LinkedHashMap<>(),original=new LinkedHashMap<>();
 private int left,top,w,h,page,fieldPage,actionPage;private String query="",group="Básico";private boolean sent;
 public MobsScreen(JsonObject data){super(Component.literal(data.get("title").getAsString()));this.data=data;if(data.has("values"))data.getAsJsonObject("values").entrySet().forEach(e->values.put(e.getKey(),e.getValue().getAsString()));original.putAll(values);if(data.has("selectedGroup"))group=data.get("selectedGroup").getAsString();if(data.has("fieldPage"))fieldPage=data.get("fieldPage").getAsInt();if(data.has("actionPage"))actionPage=data.get("actionPage").getAsInt();}
 JsonObject preserveUpgradeContext(JsonObject next){
  if(next.has("section")&&next.get("section").getAsString().equals(section())&&next.get("id").getAsString().equals(data.get("id").getAsString())){next.addProperty("selectedGroup",group);next.addProperty("fieldPage",fieldPage);next.addProperty("actionPage",actionPage);}
if(section().equals("companion_upgrades")&&next.get("section").getAsString().equals(section())&&next.get("id").getAsString().equals(data.get("id").getAsString())){next.addProperty("selectedGroup",group);String material=values.get("material");if(material!=null)for(var field:next.getAsJsonArray("fields")){var f=field.getAsJsonObject();if(f.get("key").getAsString().equals("material"))for(var choice:f.getAsJsonArray("choices"))if(choice.getAsJsonObject().get("id").getAsString().equals(material))next.getAsJsonObject("values").addProperty("material",material);}}return next;}
 private boolean dirty(){if(section().equals("companion_upgrades"))return false;return data.has("unsaved")&&data.get("unsaved").getAsBoolean()||!values.equals(original);}
 private String section(){return data.get("section").getAsString();}
 private void request(String section,String id){if(dirty()){minecraft.setScreen(new ManagerConfirmScreen(ok->{if(ok)PacketDistributor.sendToServer(new MobsNetwork.Request(section,id));else minecraft.setScreen(this);},Component.translatableWithFallback("ui.zianmobs.ebc06692e03e", "Cambios sin guardar"),Component.translatableWithFallback("ui.zianmobs.0ad24a5f8e83", "¿Salir y descartar los cambios de todas las pestañas?")));}else PacketDistributor.sendToServer(new MobsNetwork.Request(section,id));}
 @Override public void onClose(){if(dirty())minecraft.setScreen(new ManagerConfirmScreen(ok->{if(ok)super.onClose();else minecraft.setScreen(this);},Component.translatableWithFallback("ui.zianmobs.ebc06692e03e", "Cambios sin guardar"),Component.translatableWithFallback("ui.zianmobs.9100333883aa", "¿Cerrar y descartar los cambios?")));else super.onClose();}
 @Override protected void init(){fitViewport(600,400);w=560;h=376;left=(width-w)/2;top=(height-h)/2;if(section().equals("home"))home();else if(section().equals("item"))item();else if(data.has("entries"))list();else form();}
 private Button button(int x,int y,int size,String label,Runnable action){return addRenderableWidget(themed(x,y,size,20,Component.literal(label),b->action.run()));}
 private static String description(String key){return switch(key){case "companions"->"Invocar, guardar y ver la resurrección";case "npcs"->"Skins, armas y habilidades especiales";case "mobs"->"Crear y equipar criaturas normales";case "bosses"->"Jefes, dificultad y premios personales";case "zones"->"Apariciones, oleadas y enfriamiento";case "lootlist"->"Objetos, cantidades y probabilidades";case "gear"->"Equipo mejorado y objetos de prueba";default->"Ataques, ajustes y revisión de premios";};}
 private void home(){var entries=data.getAsJsonArray("entries");int col=(w-36)/2;for(int i=0;i<entries.size();i++){var row=entries.get(i).getAsJsonObject();var b=themed(left+12+(i%2)*(col+12),top+70+(i/2)*57,col,29,Component.literal(row.get("name").getAsString()),v->request(row.get("section").getAsString(),row.get("id").getAsString()));addRenderableWidget(b);}button(left+w-132,top+h-28,120,"Cerrar",this::onClose);}
 private void item(){button(left+12,top+268,w-24,"Recibir un objeto de prueba",()->send("give"));button(left+w-132,top+h-28,120,"Volver",()->request("gear",""));}
 private void renderItemInfo(GuiGraphics g){var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("zianmobs",data.get("id").getAsString()));var stack=item.getDefaultInstance();g.pose().pushPose();g.pose().translate(left+22,top+63,0);g.pose().scale(3,3,1);g.renderItem(stack,0,0);g.pose().popPose();int y=top+61;var lore=stack.get(net.minecraft.core.component.DataComponents.LORE);if(lore!=null)for(var line:lore.lines()){for(var wrapped:font.split(line,w-110)){g.drawString(font,wrapped,left+90,y,0xFFDDDDDD);y+=11;}}y+=10;for(var field:data.getAsJsonArray("fields")){var f=field.getAsJsonObject();String label=f.get("label").getAsString(),value=values.getOrDefault(f.get("key").getAsString(),"");g.drawString(font,label,left+12,y,0xFFF2C14E);y+=12;for(var line:font.split(Component.literal(value),w-24)){g.drawString(font,line,left+12,y,0xFFDDDDDD);y+=11;}y+=7;}}
 private void list(){var all=data.getAsJsonArray("entries");var search=new EditBox(font,left+12,top+49,w-24,20,Component.translatableWithFallback("ui.zianmobs.758008ebce29", "Buscar por nombre"));search.setMaxLength(80);search.setHint(Component.translatableWithFallback("ui.zianmobs.09dd165877c6", "Buscar por nombre…"));search.setValue(query);search.setResponder(v->{query=v;page=0;rebuildWidgets();});addRenderableWidget(search);setInitialFocus(search);var entries=new ArrayList<JsonObject>();for(var e:all){var row=e.getAsJsonObject();if((row.get("name").getAsString()+" "+row.get("id").getAsString()).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))entries.add(row);}int per=8,pages=Math.max(1,(entries.size()+per-1)/per);page=Math.max(0,Math.min(page,pages-1));for(int i=page*per;i<Math.min(entries.size(),(page+1)*per);i++){var row=entries.get(i);button(left+12,top+80+(i-page*per)*26,w-24,row.get("name").getAsString(),()->request(row.get("section").getAsString(),row.get("id").getAsString()));}
  button(left+12,top+h-59,32,"<",()->{page--;rebuildWidgets();}).active=page>0;button(left+48,top+h-59,32,">",()->{page++;rebuildWidgets();}).active=page+1<pages;
  if(data.has("newSection"))button(left+12,top+h-28,170,section().equals("zones")?"Crear zona…":section().equals("npcs")?"Crear NPC…":section().equals("bosses")?"Crear jefe…":"Crear nuevo…",()->request(data.get("newSection").getAsString(),""));button(left+w-132,top+h-28,120,"Inicio",()->request("home",""));
 }
 private String group(JsonObject entry,boolean action){if(entry.has("group"))return entry.get("group").getAsString();return action?AdminSections.action(section(),entry.get("id").getAsString()):AdminSections.field(section(),entry.get("key").getAsString());}
 private List<JsonObject> visible(String key,boolean action){var rows=new ArrayList<JsonObject>();for(var e:data.getAsJsonArray(key))if(group(e.getAsJsonObject(),action).equals(group))rows.add(e.getAsJsonObject());return rows;}
 private List<String> groups(){var found=new LinkedHashSet<String>();for(var f:data.getAsJsonArray("fields"))found.add(group(f.getAsJsonObject(),false));for(var a:data.getAsJsonArray("actions"))found.add(group(a.getAsJsonObject(),true));var result=new ArrayList<String>();for(String key:List.of("Básico","Combate","Habilidades","Equipo","Tamaño","Encuentro","Oleadas","Puntos","Premios","Avanzado"))if(found.contains(key))result.add(key);return result.isEmpty()?List.of("Básico"):result;}
 private void form(){var tabs=groups();if(!tabs.contains(group))group=tabs.getFirst();int tabWidth=(w-24)/tabs.size();for(int i=0;i<tabs.size();i++){String name=tabs.get(i);button(left+12+i*tabWidth,top+49,tabWidth-3,name,()->{group=name;fieldPage=actionPage=0;rebuildWidgets();}).active=!group.equals(name);}
  var fields=visible("fields",false);int pages=Math.max(1,(fields.size()+3)/4);fieldPage=Math.max(0,Math.min(fieldPage,pages-1));int col=(w-36)/2;
  for(int i=fieldPage*4;i<Math.min(fields.size(),(fieldPage+1)*4);i++){var field=fields.get(i);String key=field.get("key").getAsString(),kind=field.get("kind").getAsString();int n=i%4,x=left+12+(n%2)*(col+12),y=top+113+(n/2)*52;String value=values.getOrDefault(key,"");
   if(kind.equals("text")||kind.equals("number")){var box=new EditBox(font,x,y,col,20,Component.literal(field.get("label").getAsString()));box.setMaxLength(field.has("maxLength")?field.get("maxLength").getAsInt():kind.equals("number")?16:80);box.setValue(value);if(key.equals("id")&&value.isEmpty())box.setHint(Component.translatableWithFallback("ui.zianmobs.ffa050f07186", "Se genera al guardar"));box.setEditable((!field.has("readonly")||!field.get("readonly").getAsBoolean())&&!(section().equals("zone")&&key.equals("repeatCount")&&values.getOrDefault("encounterMode","CUSTOM").equals("CUSTOM")));box.setTooltip(Tooltip.create(Component.literal(field.get("label").getAsString()+" · "+(kind.equals("number")?"Escribe un valor dentro del rango indicado":"Los cambios se aplican al guardar"))));box.setResponder(v->values.put(key,v));addRenderableWidget(box);}else button(x,y,col,valueLabel(field,value),()->select(field,key)).active=!(section().equals("zone")&&Set.of("repeatTeam","extraBoss","scalable").contains(key)&&values.getOrDefault("encounterMode","CUSTOM").equals("CUSTOM"));
  }
  if(pages>1){button(left+12,top+194,32,"<",()->{fieldPage--;rebuildWidgets();}).active=fieldPage>0;button(left+48,top+194,32,">",()->{fieldPage++;rebuildWidgets();}).active=fieldPage+1<pages;}
  if(section().equals("zone")&&group.equals("Básico"))for(var element:data.getAsJsonArray("fields")){var f=element.getAsJsonObject();if(f.get("kind").getAsString().equals("stages"))button(left+12,top+226,w-24,"Editor avanzado: ordenar oleadas y jefes…",()->select(f,"stages"));if(values.getOrDefault("encounterMode","SIMPLE").equals("CUSTOM"))button(left+12,top+254,w-24,"Volver a configurar como antes…",()->minecraft.setScreen(new ManagerConfirmScreen(ok->{if(ok)values.put("encounterMode","SIMPLE");minecraft.setScreen(this);},Component.literal("Usar oleadas sencillas"),Component.literal("Al guardar, el mob y número de oleadas sustituirán las etapas avanzadas. El jefe final sigue siendo opcional."))));}
  var actions=visible("actions",true);int actionPages=Math.max(1,(actions.size()+3)/4);actionPage=Math.max(0,Math.min(actionPage,actionPages-1));for(int i=actionPage*4;i<Math.min(actions.size(),(actionPage+1)*4);i++){var a=actions.get(i);int n=i%4;button(left+12+(n%2)*(col+12),top+226+(n/2)*28,col,a.get("label").getAsString(),()->{if(a.has("confirm"))minecraft.setScreen(new ManagerConfirmScreen(ok->{if(ok)send(a.get("id").getAsString());else minecraft.setScreen(this);},Component.literal(a.get("label").getAsString()),Component.literal(a.get("confirm").getAsString())));else send(a.get("id").getAsString());});}
  if(actionPages>1){button(left+12,top+284,32,"<",()->{actionPage--;rebuildWidgets();}).active=actionPage>0;button(left+48,top+284,32,">",()->{actionPage++;rebuildWidgets();}).active=actionPage+1<actionPages;}
  if(!data.has("saveButton")||data.get("saveButton").getAsBoolean())button(left+12,top+h-28,190,data.has("saveLabel")?data.get("saveLabel").getAsString():"Guardar todas las pestañas",()->send("save"));button(left+w-132,top+h-28,120,"Volver",()->request(data.get("back").getAsString(),data.has("backId")?data.get("backId").getAsString():""));
 }
 private String valueLabel(JsonObject field,String value){String kind=field.get("kind").getAsString();if(kind.equals("bool"))return Boolean.parseBoolean(value)?"Activado":"Desactivado";if(kind.equals("team"))return value.isEmpty()?"Elegir criaturas…":value.split(",").length+" criaturas · Editar…";if(kind.equals("stages")){try{return JsonParser.parseString(value).getAsJsonArray().size()+" etapas · Editar encuentro…";}catch(Exception ignored){return "Crear encuentro…";}}if(kind.equals("effects"))return value.isEmpty()?"Sin efectos · Editar…":"Editar efectos…";if(field.has("choices"))for(var e:field.getAsJsonArray("choices"))if(e.getAsJsonObject().get("id").getAsString().equals(value))return e.getAsJsonObject().get("name").getAsString();return value.isEmpty()?"Seleccionar…":value;}
 private void select(JsonObject field,String key){String value=values.getOrDefault(key,""),kind=field.get("kind").getAsString();java.util.function.Consumer<String> accept=v->{values.put(key,v);minecraft.setScreen(this);};if(kind.equals("bool")){values.put(key,""+!Boolean.parseBoolean(value));rebuildWidgets();}else if(kind.equals("entity"))minecraft.setScreen(new EntitySelectorScreen(this,field.has("choices")?field.getAsJsonArray("choices"):new JsonArray(),accept));else if(kind.equals("effects"))minecraft.setScreen(new EffectsScreen(this,value,accept));else if(kind.equals("stages")){if(values.getOrDefault("encounterMode","CUSTOM").equals("SIMPLE")){try{String team=values.getOrDefault("repeatTeam","");value=team.isEmpty()?"[]":new Gson().toJson(QuickEncounter.repeat(List.of(team.split(",")),Integer.parseInt(values.getOrDefault("repeatCount","1")),Boolean.parseBoolean(values.getOrDefault("scalable","true")),values.getOrDefault("extraBoss","")));}catch(RuntimeException error){minecraft.setScreen(new ManagerConfirmScreen(ok->minecraft.setScreen(this),Component.literal("Revisa las oleadas"),Component.literal(error.getMessage()==null?"Número de oleadas inválido":error.getMessage())));return;}}minecraft.setScreen(new EncounterStagesScreen(this,field.getAsJsonArray("choices"),field.getAsJsonArray("bossChoices"),value,v->{values.put(key,v);values.put("encounterMode","CUSTOM");minecraft.setScreen(this);}));}else if(kind.equals("team"))minecraft.setScreen(new TeamScreen(this,field.getAsJsonArray("choices"),value,accept));else minecraft.setScreen(new ChoiceScreen(this,field.get("label").getAsString(),field.getAsJsonArray("choices"),false,accept));}
 private void send(String op){if(sent)return;sent=true;var json=new JsonObject();values.forEach(json::addProperty);if(section().startsWith("companion_"))PacketDistributor.sendToServer(new MobsNetwork.PetAction(UUID.fromString(data.get("token").getAsString()),op,json.toString()));else PacketDistributor.sendToServer(new MobsNetwork.Action(UUID.fromString(data.get("token").getAsString()),op,json.toString()));}
 @Override protected void renderCanvas(GuiGraphics g,int mx,int my,float dt){panel(g,left,top,w,h);String notice=data.get("notice").getAsString();g.drawString(font,font.plainSubstrByWidth(notice,w-24),left+12,top+32,0xFFF7E2AC);
  if(section().equals("item")){renderItemInfo(g);}
  else if(section().equals("home")){int col=(w-36)/2;int i=0;for(var row:data.getAsJsonArray("entries")){g.drawString(font,font.plainSubstrByWidth(description(row.getAsJsonObject().get("section").getAsString()),col),left+12+(i%2)*(col+12),top+103+(i/2)*57,0xFFBBBBBB);i++;}}
  else if(data.has("fields")){g.drawString(font,font.plainSubstrByWidth(section().equals("zone")&&group.equals("Básico")?(values.getOrDefault("encounterMode","SIMPLE").equals("SIMPLE")?"Elige el mob y cuántas oleadas. El jefe adicional se elige en Encuentro.":"Esta zona usa etapas avanzadas. Puedes editarlas o volver al modo sencillo."):AdminSections.help(section(),group),w-24),left+12,top+80,0xFFBBBBBB);var fields=visible("fields",false);int col=(w-36)/2;for(int i=fieldPage*4;i<Math.min(fields.size(),(fieldPage+1)*4);i++){var f=fields.get(i);int n=i%4;g.drawString(font,font.plainSubstrByWidth(f.get("label").getAsString(),col),left+12+(n%2)*(col+12),top+101+(n/2)*52,0xFFDDDDDD);}if(fields.size()>4)g.drawCenteredString(font,group+" · "+(fieldPage+1)+" / "+((fields.size()+3)/4),left+w/2,top+200,0xFFAAAAAA);if(section().equals("companion_upgrades")&&group.equals("Básico")&&data.has("previews")){String material=values.getOrDefault("material","");if(data.getAsJsonObject("previews").has(material)){int lineY=top+146;for(String line:data.getAsJsonObject("previews").get(material).getAsString().split("\n")){g.drawString(font,font.plainSubstrByWidth(line,w-24),left+12,lineY,0xFF95D7BC);lineY+=10;}}}if(section().equals("zone")&&group.equals("Tamaño")&&data.has("centerInfo"))g.drawString(font,data.get("centerInfo").getAsString(),left+12,top+312,0xFFF7E2AC);if(dirty())g.drawString(font,"Cambios sin guardar",left+12,top+h-45,0xFFF2C14E);}
  else {g.drawString(font,"Página "+(page+1)+" · busca o selecciona una opción",left+92,top+h-53,0xFFAAAAAA);if(data.getAsJsonArray("entries").isEmpty())g.drawCenteredString(font,"Todavía no hay elementos. Usa Crear nuevo para empezar.",left+w/2,top+132,0xFFBBBBBB);}
  renderWidgets(g,mx,my,dt);
 }
}
